  ('"I hope you ___ a great time in Bodrum next week." Boşluğa hangisi gelebilir?', 'have', ['had had', 'would have had', 'having'], '"hope" ile gelecek anlamında present simple ya da will kullanılabilir: "I hope you have/will have..."'),
  ('"Make sure you ___ the door when you leave." Boşluğa hangisi uygundur?', 'lock', ['will lock', 'locked', 'had locked'], '"make sure (that)" kalıbında gelecek anlamı için genellikle present simple kullanılır.'),
  ('"I took a jacket in case it ___ cold." Geçmiş bir anlatımda boşluğa hangisi uygundur?', 'got', ['gets', 'will get', 'has got'], 'Geçmişte anlatılan bir önlemde "in case" sonrasında past simple kullanılır.'),
  ('"I bet he ___ late again tomorrow." Boşluğa hangisi gelebilir?', '\'ll be', ['was being', 'had been', '\'s been'], '"I bet" ile gelecek tahmininde will ya da present simple kullanılabilir; seçenekler arasında uygun olan "\'ll be"dir.'),
  ('"I ___ you that the money will be returned." Bir güvence verme eylemini konuşarak gerçekleştirmek için boşluğa hangisi uygundur?', 'assure', ['am assuring', 'have assured', 'was assuring'], 'Söylenerek gerçekleştirilen edimsel fiiller (promise, assure, suggest, apologise) present simple ile kullanılır.'),
