  ('"How long ___ in Spain next summer?" Gelecekteki bir planın süresini sormak için boşluğa hangisi uygundur?', 'will you stay', ['have you stayed', 'did you stay', 'had you stayed'], 'Gelecekteki bir dönem için süre sorulurken will ya da going to kullanılır.'),
  ('"How many times ___ the exam before you passed it?" Boşluğa hangisi uygundur?', 'had you taken', ['have you taken', 'are you taking', 'will you take'], 'Geçmişteki bir andan (geçme) önce tekrarlanan eylemin sayısı past perfect ile sorulur.'),
  ('"By noon, they will have been driving for six hours." cümlesindeki zamanın adı nedir?', 'Future perfect continuous', ['Future continuous', 'Past perfect continuous', 'Present perfect continuous'], '"will have been + -ing" yapısı future perfect continuous zamanıdır.'),
  ('Past perfect continuous zamanının olumlu yapısı hangisidir?', 'had been + fiil-ing', ['has been + fiil-ing', 'was being + fiil-ing', 'would be + fiil-ing'], 'Past perfect continuous: özne + had been + V-ing.'),
  ('Hangi cümle future continuous zamanındadır?', 'We\'ll be flying over the Alps at noon.', ['We\'ll have flown over the Alps by noon.', 'We\'ve been flying over the Alps.', 'We were flying over the Alps at noon.'], 'Future continuous: will be + V-ing.'),
  ('Aşağıdaki cümlelerin hangisinde eylem hem geçmişte başlamış hem de şu anda sürmektedir?', 'They\'ve been living in Rize since 2012.', ['They lived in Rize in 2012.', 'They\'d lived in Rize before 2012.', 'They were living in Rize in 2012.'], 'Present perfect continuous + since, geçmişte başlayıp hâlâ süren eylemi anlatır.'),
  ('Aşağıdakilerden hangisi present perfect continuous zamanının olumsuz biçimine örnektir?', 'I haven\'t been sleeping well lately.', ['I didn\'t sleep well last night.', 'I hadn\'t slept well before.', 'I won\'t be sleeping well tonight at all.'], 'Present perfect continuous olumsuz: have/has not been + V-ing.'),
